package com.agriconnect.logistics;import static org.assertj.core.api.Assertions.*;import java.util.*;import org.h2.jdbcx.JdbcDataSource;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.*;import org.springframework.jdbc.core.simple.JdbcClient;
class OrderEventConsumerTest{@Test void duplicateEventCreatesOneShipmentAndOneReceipt(){JdbcDataSource ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:consumer;MODE=PostgreSQL;DB_CLOSE_DELAY=-1");JdbcTemplate j=new JdbcTemplate(ds);j.execute("create table shipments(id bigint generated by default as identity primary key,order_id bigint unique,buyer_id bigint,farmer_ids varchar(255),logistics_user_id bigint,pickup_address varchar(255),delivery_address varchar(255),status varchar(20))");j.execute("create table processed_events(event_id uuid primary key,processed_at timestamp default current_timestamp)");OrderEventConsumer c=new OrderEventConsumer(JdbcClient.create(ds));UUID id=UUID.randomUUID();Map<String,Object>event=Map.of("eventId",id,"payload",Map.of("orderId",10,"buyerId",20,"farmerIds","30","deliveryAddress","B"));c.consume(event);c.consume(event);assertThat(j.queryForObject("select count(*) from shipments",Integer.class)).isEqualTo(1);assertThat(j.queryForObject("select count(*) from processed_events",Integer.class)).isEqualTo(1);}}
